    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (tid, '126. A patient on warfarin presents with INR 8.5 and active GI bleeding. What is the most rapid reversal agent?', '["Vitamin K 10mg IV alone", "4-factor prothrombin complex concentrate (4F-PCC) plus vitamin K", "Fresh frozen plasma (FFP) only", "Aminocaproic acid"]', 1, '4F-PCC provides rapid, complete reversal of warfarin within 15-30 minutes. Vitamin K is given concurrently for sustained effect (takes 6-24 hours). FFP is slower, requires large volumes, and risks volume overload.'),
    (tid, '127. A patient on dabigatran (Pradaxa) presents with life-threatening intracranial hemorrhage. What is the specific reversal agent?', '["Vitamin K", "Idarucizumab (Praxbind)", "Protamine sulfate", "Tranexamic acid"]', 1, 'Idarucizumab is a monoclonal antibody fragment that specifically binds dabigatran with immediate and complete reversal. Dose: 5g IV (two 2.5g vials). It does not reverse other DOACs.'),
    (tid, '128. What reverses rivaroxaban and apixaban (factor Xa inhibitors) in life-threatening bleeding?', '["Idarucizumab", "Andexanet alfa (Andexxa)", "Protamine sulfate", "Desmopressin"]', 1, 'Andexanet alfa is a recombinant modified factor Xa that acts as a decoy, binding and sequestering factor Xa inhibitors (rivaroxaban, apixaban, edoxaban). 4F-PCC is an alternative if andexanet is unavailable.'),
    (tid, '129. A patient receiving IV heparin develops acute thrombocytopenia (platelets drop from 200K to 60K) on day 7. What is the most likely diagnosis?', '["Dilutional thrombocytopenia", "Heparin-induced thrombocytopenia type II (HIT)", "ITP", "DIC"]', 1, 'HIT type II is an immune-mediated prothrombotic disorder occurring 5-14 days after heparin exposure. Platelet count drops >50%. Paradoxically causes thrombosis. Stop ALL heparin and start argatroban or bivalirudin.'),
    (tid, '130. What is the antidote for heparin overdose?', '["Vitamin K", "Protamine sulfate", "Idarucizumab", "Aminocaproic acid"]', 1, 'Protamine sulfate reverses unfractionated heparin (1mg protamine per 100 units heparin given in last 2 hours). It partially reverses LMWH (~60% of anti-Xa activity). Give slowly to avoid hypotension and anaphylactoid reactions.'),
    (tid, '131. Which beta-blocker is preferred in the ED for acute rate control due to its ultra-short half-life?', '["Metoprolol", "Esmolol", "Atenolol", "Propranolol"]', 1, 'Esmolol has an elimination half-life of 9 minutes, making it ideal for titration in the ED. If adverse effects occur (hypotension, bradycardia), they resolve within minutes of stopping the infusion.'),
    (tid, '132. A patient with decompensated heart failure is started on IV milrinone. What is the mechanism of action?', '["Beta-1 agonism", "Phosphodiesterase-3 inhibition (inodilator)", "Alpha-1 agonism", "Calcium channel blockade"]', 1, 'Milrinone inhibits PDE-3, increasing intracellular cAMP. This produces positive inotropy AND vasodilation (inodilator). Unlike dobutamine, it does not work through beta-receptors and is effective in beta-blocked patients.'),
    (tid, '133. Which vasopressor acts primarily on alpha-1 receptors with minimal beta effect?', '["Dobutamine", "Phenylephrine", "Isoproterenol", "Dopamine"]', 1, 'Phenylephrine is a pure alpha-1 agonist causing vasoconstriction without inotropy or chronotropy. It increases SVR and MAP but can reflexively decrease heart rate. Used when tachycardia limits norepinephrine use.'),
    (tid, '134. A patient on a beta-blocker overdose presents with bradycardia and hypotension unresponsive to atropine and fluids. What is the antidote?', '["Naloxone", "Glucagon 3-5mg IV bolus", "Flumazenil", "Calcium chloride"]', 1, 'Glucagon bypasses the blocked beta-receptor and activates adenylyl cyclase directly, increasing cAMP. This produces positive chronotropy and inotropy. Dose: 3-5mg IV bolus, then 3-5mg/hr infusion.'),
    (tid, '135. A patient presents with calcium channel blocker overdose (verapamil). HR 40, BP 70/40. What is the first-line treatment?', '["Atropine alone", "IV calcium chloride (or gluconate), high-dose insulin-euglycemia therapy (HIE)", "IV adenosine", "Activated charcoal only"]', 1, 'CCB toxicity is treated with IV calcium (increases extracellular calcium to overcome channel blockade), HIE (insulin 1 U/kg bolus then 1 U/kg/hr with dextrose), vasopressors, and lipid emulsion in severe cases.'),
    (tid, '136. What is the mechanism by which high-dose insulin therapy works in calcium channel blocker toxicity?', '["Reverses calcium channel blockade", "Improves myocardial glucose utilization and enhances inotropy", "Lowers serum potassium", "Increases heart rate"]', 1, 'In CCB toxicity, the heart shifts from fatty acid to glucose metabolism. High-dose insulin enhances myocardial glucose uptake, improving contractility (inotropy) independent of calcium channels.'),
    (tid, '137. A patient with suspected tricyclic antidepressant (TCA) overdose has a wide QRS (140ms) on ECG. What is the treatment?', '["IV flumazenil", "Sodium bicarbonate boluses to narrow the QRS", "IV calcium", "Physostigmine"]', 1, 'TCA toxicity causes sodium channel blockade leading to QRS widening. Sodium bicarbonate (1-2 mEq/kg IV bolus) overcomes the sodium channel blockade and alkalinizes serum, reducing free drug binding to channels.'),
    (tid, '138. At what QRS width in TCA overdose should sodium bicarbonate be administered?', '["Any widening from baseline", "QRS >100 ms", "QRS >200 ms", "Only if QRS >160 ms with seizures"]', 1, 'Sodium bicarbonate should be given when QRS >100 ms in suspected TCA overdose. The goal is to narrow QRS to <100 ms and maintain serum pH at 7.45-7.55. It is both treatment and prevention of arrhythmias.'),
    (tid, '139. What is the role of IV lipid emulsion (Intralipid) in cardiac emergencies?', '["Nutritional support only", "Antidote for lipophilic drug toxicity causing cardiovascular collapse (local anesthetics, CCBs, beta-blockers)", "Treatment for hyperkalemia", "Fluid resuscitation"]', 1, 'IV lipid emulsion acts as a lipid sink, sequestering lipophilic drugs from cardiac tissue. Originally developed for local anesthetic systemic toxicity (LAST), it is now used for refractory cardiovascular collapse from multiple toxins.'),
    (tid, '140. A patient presents with digoxin toxicity and complete heart block. Atropine fails. What is the definitive treatment?', '["Repeat atropine", "Transcutaneous pacing and digoxin-specific Fab antibodies", "IV amiodarone", "Cardioversion"]', 1, 'Digoxin Fab fragments are definitive for digoxin toxicity. Temporary pacing bridges until Fab takes effect. Cardioversion and calcium are relatively contraindicated as they can worsen digoxin-induced arrhythmias.'),
    (tid, '141. Emergency transcutaneous pacing is indicated in which of the following situations?', '["Stable sinus bradycardia", "Symptomatic bradycardia unresponsive to atropine", "Atrial fibrillation", "Narrow complex tachycardia"]', 1, 'TCP is indicated for hemodynamically unstable bradycardia refractory to atropine, high-degree AV block (Mobitz II, complete heart block), and as a bridge to transvenous pacing.'),
    (tid, '142. During emergency transcutaneous pacing, how do you confirm mechanical capture?', '["Pacer spikes visible on monitor", "Palpable pulse corresponding to the pacing rate and improvement in hemodynamics", "Patient reports chest discomfort", "SpO2 improvement"]', 1, 'Electrical capture (wide QRS after each pacer spike) must be followed by confirmation of mechanical capture — a palpable pulse at the pacing rate with improved BP and perfusion. Electrical capture alone is insufficient.'),
    (tid, '143. What is the Seldinger technique used for in cardiac emergencies?', '["Pericardiocentesis only", "Percutaneous vascular access using a guidewire for central lines, PA catheters, and transvenous pacers", "Chest tube placement", "Cricothyrotomy"]', 1, 'The Seldinger technique (needle → guidewire → dilator → catheter) is the standard method for gaining central venous access (IJ, subclavian, femoral) for CVCs, transvenous pacers, and PA catheters.'),
    (tid, '144. A patient needs emergent central venous access during cardiac arrest. Which site is preferred to avoid interrupting chest compressions?', '["Internal jugular vein", "Subclavian vein", "Femoral vein", "Peripheral IV"]', 2, 'Femoral vein access does not require pausing CPR (unlike IJ or subclavian which are near the chest compression site). It also has lower pneumothorax risk. IO access is the preferred alternative to IV during arrest.'),
    (tid, '145. What is the advantage of intraosseous (IO) access over peripheral IV in cardiac arrest?', '["Lower infection rate", "Faster to establish with equivalent drug delivery to central venous access", "Better for blood sampling", "Less painful"]', 1, 'IO access can be established in <60 seconds with a power drill and provides drug delivery equivalent to central venous access. All ACLS medications and fluids can be given IO. Preferred when IV access is delayed.'),
    (tid, '146. Synchronized cardioversion for atrial fibrillation with hemodynamic instability typically starts at what energy level?', '["50 J biphasic", "120-200 J biphasic", "360 J monophasic", "10 J biphasic"]', 1, 'Atrial fibrillation cardioversion typically starts at 120-200 J biphasic (or 200 J monophasic). Atrial flutter and SVT can be cardioverted at lower energies (50-100 J). Monomorphic VT starts at 100 J.'),
    (tid, '147. A patient on metformin presents in cardiac arrest with severe lactic acidosis (pH 6.9, lactate 18). In addition to ACLS, what treatment may be lifesaving?', '["IV dextrose", "Emergent hemodialysis", "IV calcium", "Activated charcoal"]', 1, 'Metformin-associated lactic acidosis (MALA) can cause refractory cardiovascular collapse. Hemodialysis removes metformin and corrects acidosis. Sodium bicarbonate is a temporizing measure.'),
    (tid, '148. What is the recommended approach when a patient with a left ventricular assist device (LVAD) presents with cardiac arrest?', '["Standard CPR with chest compressions", "Do NOT perform chest compressions; assess LVAD function, auscultate for hum, and check device parameters", "Defibrillation only", "Immediate LVAD removal"]', 1, 'LVAD patients may be pulseless at baseline (continuous flow). Check for LVAD hum (auscultate), verify power/connections, and check MAP with Doppler. Chest compressions risk dislodging the device and are avoided unless no flow confirmed.'),
    (tid, '149. What is the Bezold-Jarisch reflex and when does it occur in cardiac emergencies?', '["Tachycardia in response to pain", "Bradycardia, hypotension, and vasodilation triggered by activation of cardiac mechanoreceptors during inferior MI or spinal anesthesia", "Hypertension from catecholamine surge", "Reflex tachycardia from nitrate use"]', 1, 'The Bezold-Jarisch reflex causes paradoxical bradycardia and hypotension via vagal activation. It occurs in inferior MI (especially with RV involvement), neuraxial anesthesia, and after certain medications.'),
    (tid, '150. A patient with prosthetic mitral valve presents with acute dyspnea, hemolysis, and a muffled prosthetic click on auscultation. What is the likely emergency?', '["Endocarditis", "Prosthetic valve thrombosis causing acute obstruction", "Paravalvular leak", "Patient-prosthesis mismatch"]', 1, 'Prosthetic valve thrombosis causes acute obstruction with hemodynamic collapse. Muffled or absent prosthetic clicks suggest restricted leaflet motion. TEE confirms diagnosis. Treatment: thrombolytics (if not surgical candidate) or emergent surgery.');
